import { mapVscodeThemeToDryl } from "./vscode-theme-map.mjs";

const APPLIED_VARS = new Set();

const DRYL_TOKEN_KEYS = [
  "--background-primary-base",
  "--background-secondary-base",
  "--background-tertiary-base",
  "--list-hover-background-base",
  "--border-primary-base",
  "--border-secondary-base",
  "--accent-primary",
  "--accent-secondary",
  "--accent-border",
  "--danger-primary",
  "--warning-primary",
  "--success-primary",
  "--info-primary",
  "--highlight-primary",
  "--text-primary",
  "--text-secondary",
  "--text-muted",
];

const BASE_TO_RESOLVED = {
  "--background-primary-base": "--background-primary",
  "--background-secondary-base": "--background-secondary",
  "--background-tertiary-base": "--background-tertiary",
  "--list-hover-background-base": "--list-hover-background",
  "--border-primary-base": "--border-primary",
  "--border-secondary-base": "--border-secondary",
};

export function applyVscodeThemeToRoot(theme, root = globalThis.document?.documentElement) {
  if (!root || typeof root.style?.setProperty !== "function") {
    throw new Error("Invalid root element for theme preview");
  }
  const mapped = mapVscodeThemeToDryl(theme);
  const appliedVars = [];
  const setVar = (name, value) => {
    root.style.setProperty(name, value);
    APPLIED_VARS.add(name);
    appliedVars.push(name);
  };
  for (const name of DRYL_TOKEN_KEYS) {
    const value = mapped[name];
    const resolved = BASE_TO_RESOLVED[name];
    if (!value) {
      root.style.removeProperty(name);
      APPLIED_VARS.delete(name);
      if (resolved) {
        root.style.removeProperty(resolved);
        APPLIED_VARS.delete(resolved);
      }
      continue;
    }
    setVar(name, value);
    if (resolved) setVar(resolved, `var(${name})`);
  }
  if (theme.type === "dark" || theme.type === "light") {
    root.style.colorScheme = theme.type;
    APPLIED_VARS.add("color-scheme");
  }
  return { appliedCount: appliedVars.length, appliedVars };
}

export function clearVscodeThemeFromRoot(root = globalThis.document?.documentElement) {
  if (!root) return;
  for (const name of APPLIED_VARS) {
    root.style.removeProperty(name);
  }
  APPLIED_VARS.clear();
}
